import random
from collections import Counter

loot = ["Common Sword", "Rare Shield", "Epic Helm", "Legendary Ring"]
weights = [40, 30, 20, 10]

# Generate drops
drops = random.choices(loot, weights=weights, k=10)
drop_counts = Counter(drops)

# Generate damage bonuses
print("Loot drops:")
for item, count in drop_counts.items():
    print(f"  {item} ({count})")

print("\nDamage bonuses:")
for item in loot:
    if item in drop_counts:
        if "Common" in item:
            bonus = random.randint(1, 5)
        elif "Rare" in item:
            bonus = random.randint(6, 10)
        elif "Epic" in item:
            bonus = random.randint(11, 20)
        elif "Legendary" in item:
            bonus = random.randint(21, 50)
        else:
            bonus = 0
        print(f"  {item}: {bonus}")
